SELECT o.*, IFNULL((SELECT GROUP_CONCAT(title) FROM room_device_classify c WHERE FIND_IN_SET(c.classify_id, r.classify_ids)),"暂未填写") AS classifyName FROM orders o, `shops_room` r
o.`room_id` = r.`room_id`
and o.user_id = #{orderVo.userId}
and o.order_status = #{orderVo.orderStatus}
order by create_time desc
